WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true ) ) ) SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT sum( "t0"."rating" ) AS "rating" ) AS "%")) AS "sum" , row_to_json((SELECT "%" FROM (SELECT avg( "t0"."rating" ) AS "rating" ) AS "%")) AS "avg" , row_to_json((SELECT "%" FROM (SELECT min( "t0"."name" ) AS "name" , min( "t0"."nickname" ) AS "nickname" ) AS "%")) AS "min" , row_to_json((SELECT "%" FROM (SELECT max( "t0"."name" ) AS "name" , max( "t0"."nickname" ) AS "nickname" ) AS "%")) AS "max" ) AS "%")) AS "aggregate" ) AS "%")) FROM "r0" AS "t0"
